import{_ as r,C as t,o as l,c as i,j as e,a as o,E as n,a5 as h}from"./chunks/framework.DNkHA0lr.js";const g=JSON.parse('{"title":"新经济时代的7大数字职业路径","description":"","frontmatter":{"title":"新经济时代的7大数字职业路径","originalTitle":"The 7 Digital Career Paths (In The New Economy)","date":"2024-01-13","originalUrl":"https://thedankoe.com/letters/the-7-digital-career-paths-from-zero-experience-to-advanced/","minutes":14,"sourceHash":"953661eac30c546d30d2bff4c61313e3bc41c6b5866af574b14c3d09f1616fc9","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-7-digital-career-paths-from-zero-experience-to-advanced/"}]]},"headers":[],"relativePath":"letters/the-7-digital-career-paths-from-zero-experience-to-advanced.md","filePath":"letters/the-7-digital-career-paths-from-zero-experience-to-advanced.md"}'),s={name:"letters/the-7-digital-career-paths-from-zero-experience-to-advanced.md"};function c(d,p,u,f,b,m){const a=t("ArticleMeta");return l(),i("div",null,[p[0]||(p[0]=e("h1",{id:"新经济时代的7大数字职业路径",tabindex:"-1"},[o("新经济时代的7大数字职业路径 "),e("a",{class:"header-anchor",href:"#新经济时代的7大数字职业路径","aria-label":'Permalink to "新经济时代的7大数字职业路径"'},"​")],-1)),n(a),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/7wMY5MsKEkM?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>在我的整个童年时期，我只知道人生只有一条路可走。</p><p>上学，找份工作，退休时带着刚好能撑到死的那点钱。</p><p>父母、老师和朋友不断给我灌输这些信息，巩固了那种狭隘的世界观。</p><p>注入我脑海中的梦想是：</p><ul><li>在学校取得好成绩</li><li>选一个能提高我赚钱潜力的专业</li><li>志向远大，成为医生、律师或工程师之类的角色</li></ul><p>我没意识到自己正被训练成社会的一个可替代部件。</p><p>我知道有百万富翁、数字游民，还有人靠做自己热爱的事情获得创意收入——但我从来没觉得这也是一种可能。</p><p>它看起来太遥不可及了。太远了。我的脑子根本无法想象去做这件事，因为我所知道的唯一一件事，就是那些从不决定去未知领域追求梦想的人一遍遍重复的“找份高薪工作”。</p><p>最终，数字世界的潜力向我显现了。</p><p>在八年级时，我最好的朋友和我一起上了施罗德先生（Mr. Schroeder）的数学课。</p><p>他也是课后举重课的老师。</p><p>我朋友和我体格都不错。我已经长到了6英尺5英寸高，所以他半强迫地逼着我们去参加了课后举重课。</p><p>我仍然记得第一次举重时感觉有多怪异。与今天感觉强壮而稳定的状态完全不同。</p><p>为了卧推65磅，我那瘦弱的胳膊会不受控制地颤抖。那种酸痛感简直是另一个次元的。我不想再去，但我还是去了。</p><p>随着时间的推移和进步，我变得痴迷起来。</p><p>在高中，我放学后的日常是：</p><ul><li>喝练前氮泵</li><li>抓起健身包</li><li>回顾我的训练计划（当时用的是Ogus 7/5/3）</li><li>和朋友在健身房挥汗如雨</li><li>回家，泡一杯蛋白粉，然后看YouTube视频</li></ul><p>我唯一看的频道就是健身频道。</p><p>马特·奥古斯（Matt Ogus）、克里斯·拉瓦多（Chris Lavado）、斯科特·赫尔曼（Scott Herman）、艾略特·胡尔斯（Elliot Hulse）、克里斯·琼斯（Chris Jones）……</p><p>如果你了解YouTube健身的这个时代，不用谢我唤起你脑海里的美好回忆。</p><p>顿悟：</p><p>这些创作者（creators）在做着他们热爱的事情，在大规模地影响他人，并让人们看到自身的潜力。</p><p>就在这时，我开始意识到并去解构我该如何做到同样的事。</p><p>经历了多年的失败——做过健身YouTube频道、数字艺术Instagram主页、好几家营销机构，最终在通过自由网页设计取得成功的同时转型成为一名创作者……我找到了我在寻找的东西。</p><p>我来这里是为了帮你理清这条路。</p><p>这条通往目标、利润与平静的路。</p><p>在开始之前：</p><ol><li>《专注的艺术》（<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art Of Focus</a>）现已在亚马逊上架。这本书包含了我的实用哲学，帮助你寻找意义、重塑自我，并创造你理想的未来。</li><li>Kortex大学正在接受申请。下一期的开课日期是26号。如果你感兴趣，最好现在就申请，这样你就有时间在截止前加入。<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">在此开启你的90天数字职业生涯</a>。</li></ol><h2 id="创作者就是去中心化的媒体公司" tabindex="-1">创作者就是去中心化的媒体公司 <a class="header-anchor" href="#创作者就是去中心化的媒体公司" aria-label="Permalink to &quot;创作者就是去中心化的媒体公司&quot;">​</a></h2><p>媒体运转着这个世界。</p><p>媒体塑造了文化。</p><p>媒体将人们禁锢在枷锁之中。</p><p>媒体让人们发现自己的潜力。</p><p>你正在看着的电脑？屏幕上的所有东西都是媒体。</p><p>你开车路过的广告牌？路边的商店？你旁边的汽车品牌？收音机里的歌？全都是媒体。</p><p>我们正处于一场观念的精神战争中。</p><p>媒体是内容的同义词。</p><p>而内容可以说比媒体更加包罗万象，所以从现在起，我们将使用“内容”这个词。</p><p>你在意识中拥有的每一件事物都是内容。<strong>是你注意力的内容。</strong></p><p>用心的内容能帮助人们成长、进化并扩展自我认知。</p><p>盲目的内容则助长衰退、停滞，并让人们固守自己那低级发展的自我。</p><p>这就是我们在玩的游戏。</p><p>你要么通过传播来提升人类的福祉。</p><p>要么通过创作内容来摧毁人类的福祉。</p><p>无论你是否将其贬低为一份新时代的网络工作，你都是一个内容创作者。</p><p>你写短信。你跟同龄人交流。你用说服力为你赢得职业生涯。你正在做“内容创作者”所做的一切，但只用了一丁点杠杆（leverage）。</p><p>正如巴拉吉（Balaji）所说：“先是实体的，然后是数字的，最后是原生数字的。”</p><p>在接下来的几十年内，你将成为一名互联网内容创作者。这将是生存的必然要求。</p><p>以下是你的准备方法。</p><h3 id="你在虚拟现实中的角色" tabindex="-1">你在虚拟现实中的角色 <a class="header-anchor" href="#你在虚拟现实中的角色" aria-label="Permalink to &quot;你在虚拟现实中的角色&quot;">​</a></h3><p>你不是什么“创作者”。</p><p>你不是什么“个人品牌”。</p><p>你只是一个有意识地管理自己的互联网化身，并关注它将如何与数字社会互动的人。</p><p>你已经有一个账号了。</p><p>你是一个消费者吗——沉浸在价值或梗图中，却没有任何回报？</p><p>还是一个创作者——用你创造的价值为人类做出贡献？</p><p>这不是一个互联网现象。</p><p>大众是消费者。他们吸附在政府、父母、学校系统上，像狂风中的鸟儿一样随风飘荡。生活降临在他们身上。生活被指派给他们。他们没有意识到，正是他们在用注意力为社会提供燃料。</p><p>少数精选出来的人是创作者。他们贡献的比索取的更多。他们通过控制自己的注意力来掌控命运。他们通过捕获他人的注意力，并用有价值的内容扩展他人的意识，来促进他人的命运发展。</p><p>注意力是第一步。</p><p>注意力是存在的根源。</p><p>如果你想要获得任何形式的成功，你就必须捕获注意力。</p><p>“但是Dan，我不想去捕获注意力，这看起来不道德。”</p><p>你哪怕坐下来思考过这件事5分钟吗？还是在人云亦云地复述你在网上看到的一个糟糕观点？</p><p>你会因为现在正把注意力花在读这篇文章上而生气吗？</p><p>你的注意力被吸引到重要的事情上是不道德的吗？</p><p>当你收到通知时，你的注意力转移到手机上，这不道德吗？</p><p>你想让任何人都无法捕获你的注意力吗？所以你只想余生都坐在虚空中，永远不跟任何东西互动？</p><p>醒醒吧。</p><p>学会去说服。</p><p>如果你不这么做，你就是在主动选择让不道德的人赢得这场精神战争。</p><p>你退出生活的游戏并不代表你很“清醒”。可以说，你比那些至少能通过销售的产品提供一丁点价值（确实改善了某些人的生活……对另一些人则不然，但这没关系）的滑头商人还要不清醒。</p><h3 id="如果你不创造产品-你就无法掌控自己的未来" tabindex="-1">如果你不创造产品，你就无法掌控自己的未来 <a class="header-anchor" href="#如果你不创造产品-你就无法掌控自己的未来" aria-label="Permalink to &quot;如果你不创造产品，你就无法掌控自己的未来&quot;">​</a></h3><blockquote><p>凭借你的智慧——而不是你的时间、劳动或外表——来赚钱的能力，才是你掌控自己做什么以及赚多少钱的方法。<a href="https://twitter.com/thedankoe/status/1700526734976618758" target="_blank" rel="noreferrer"></a></p><p>《专注的艺术》（<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art Of Focus</a>）</p></blockquote><p>来回答一个常见的肤浅（但很好的）问题：</p><p>“我如何在网上赚钱？”</p><p>我不确定为什么学校里不教这个，但答案是，不是靠像YouTube广告费或X平台变现那样的平台收益。</p><p>我在X平台上每月大约赚300美元，在YouTube上每月大约赚1万美元。</p><p>那是一笔很棒的、能改变生活的钱，但我花了5年时间才达到这一步。</p><p>在这同样的5年里，我的总收入略高于500万美元。其中90%以上我都装进了自己的腰包。</p><p>我在2019年11月开始玩Twitter。在此之前，我是一名自由网页设计师。</p><p>2020年，我赚了10万美元。</p><p>试着通过运营一个YouTube频道且只靠广告费来做到这一点吧。</p><p>简而言之，你如何在网上赚钱？真正的钱？</p><p>你要创办一家企业。</p><p>你需要一个产品和一群客户。</p><p>很震惊吧，我知道。</p><p>作为一家企业，你的工作就是吸引人们来了解一个产品，这样他们才能把钱交给你来换取它。</p><p>显然，里面还有很多门道，我在之前的信件里讲过了。</p><p>现在，奇迹发生的时刻到了：</p><p>你写内容。</p><p>你努力让它被更多人看到（这是至关重要的一步，不管我怎么强调，所有人都忽视了它，因为正是在这一步才真正需要下苦功夫）。</p><p>喜欢你内容的人会关注你。</p><p>你创造一个产品。</p><p>你营销这个产品。</p><p>你的主要杠杆是内容。</p><p>如果你能获得1个粉丝，你就能获得10万个。</p><p>你的次要杠杆是营销。</p><p>如果你能赚1美元，你就能赚10万美元。</p><p>这就是新经济。</p><p>这就是个人如何借助过去5年涌现的技术（因此大多数人仍然觉得这个想法很疯狂，在你们眼里它还不“正常”），通过做自己喜欢的事情来赚取收入的方式。</p><h2 id="_7条数字职业路径" tabindex="-1">7条数字职业路径 <a class="header-anchor" href="#_7条数字职业路径" aria-label="Permalink to &quot;7条数字职业路径&quot;">​</a></h2><p>重申一下，你积累受众是为了给你的产品建立一个流量源。</p><p>这是第一步。</p><p>注意我没有说“你在写内容”，我说的是你在“积累受众”。</p><p>这两者有细微的差别。</p><p>写作是必须的，但大多数人就止步于此了。他们不努力让自己的内容被分享，不努力在这个圈子里打响自己的名号，也不去结交能帮助他们成长的朋友。我<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">在这里</a>讨论了增长机制，但我们在<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex大学</a>也提供了一个愿意帮助你成长的人脉网络。</p><p>那么，你该如何利用你积累的受众来打造一份事业？来让收入来源多样化？来为自己铺设一个通向自由的未来？</p><p>我将按照从最入门级到最高阶的顺序排列这些路径：</p><h3 id="_1-为另一个创作者或品牌工作" tabindex="-1">1) 为另一个创作者或品牌工作 <a class="header-anchor" href="#_1-为另一个创作者或品牌工作" aria-label="Permalink to &quot;1) 为另一个创作者或品牌工作&quot;">​</a></h3><p>你的个人主页就是你的数字简历。</p><p>你的内容就是你吸引机会和工作的方式。</p><p>越多的人知道你是做什么的 = 越多的人可能会雇佣你。</p><p>现在，理解一下网络效应……</p><p>如果你“只有”1000个粉丝，但这些粉丝每个人都有200到500个粉丝，而那里的每个粉丝又都有200到500个粉丝……</p><p>那么你就拥有了一个由4000万到2.5亿人组成的间接网络，可以帮你传播你的名字。</p><p>当然，前提是你的每一个粉丝都分享你的帖子（这不可能）。而且我们还必须考虑互动率、内容质量、那些粉丝是否会登录社交媒体，以及他们刚好认识需要你这种经验水平工作的人的几率。</p><p>所以，让我们给出非常慷慨的估计：每个月有10000个人多少知道你是谁、做什么的。</p><p>把它乘以6到12个月的努力，我发现想在这个游戏里失败真的太难了。</p><p><strong>所需技能：</strong></p><p>如果你想为另一个创作者或品牌工作，你需要练习任何有助于你个人品牌增长的技能。</p><ul><li>社交媒体增长</li><li>内容写作</li><li>邮件文案</li><li>漏斗构建（落地页等）</li><li>品牌设计</li><li>线索挖掘或营销</li></ul><p>挑一个，学习它，实践它，然后挑下一个，学习它，实践它。</p><p>然后，写写关于它的内容。给出建议。去教别人。有些创作者可能会主动联系你。有些则需要你去主动联系。这些都不是百分之百保证的，但你可以通过增长你的受众以及联系更多创作者，提出用你的技能集帮助他们，来增加成功的几率。</p><p>反正你迟早得把这些全学一遍。</p><p>你不需要掌握所有的技能就能取得一些成功，但继续提升你自己，并进而提升你的业务，才是唯一明智的做法。</p><h3 id="_2-开启服务型业务" tabindex="-1">2) 开启服务型业务 <a class="header-anchor" href="#_2-开启服务型业务" aria-label="Permalink to &quot;2) 开启服务型业务&quot;">​</a></h3><p>如果你拥有能为你带来结果的技能，你可以直接开始做这个。</p><p>或者，你可以将你从与其他创作者（creator）合作中学到的东西转化为一项业务，并将其他创作者作为客户来提供帮助。</p><p>服务型业务就是客户型业务。你收取 1000 到 50,000 美元（在<em>极</em>高端的情况下），用你的技能来帮助客户。</p><p>服务型业务的类型（当我们刚开始在线上起步时需要关注的）：</p><ul><li>辅导（Tutoring）——类似于教练指导，但你是将自己的技能一对一地教给另一个人。比如我每周通过电话教某人网页设计。</li><li>自由职业（Freelancing）——显而易见，你用你的任何技能帮助客户，比如网页设计就是一个很好的起点——但你应该学习如何打造更好的报价（offer），因为光靠卖那么简单的东西你是做不久的。</li><li>教练或咨询（Coaching or consulting）——你帮助别人落实你的技能或系统。你不是像自由职业者那样替他们做，而是和他们一起做并指导他们。</li><li>代理机构（Agency）——把代理机构想象成有员工或外包人员来提供服务的自由职业业务。如果你没有员工或外包人员，你就不是代理机构。</li></ul><p>你从服务型业务开始，因为你的受众群体还不够大，不足以支撑另一种类型的业务。</p><p>你每个月只需要 2-4 个客单价在 2000 美元左右的客户，就能替代你原来的收入并赚到一笔可观的钱。</p><p>你必须学习获客（lead-generation）策略，比如主动出击（direct outreach）或发布针对性内容，以此来拿下客户。</p><h3 id="_3-联盟营销" tabindex="-1">3) 联盟营销 <a class="header-anchor" href="#_3-联盟营销" aria-label="Permalink to &quot;3) 联盟营销&quot;">​</a></h3><p>我不太喜欢把联盟营销作为你的唯一收入来源。</p><p>在你自己的产品和内容中推广软件和其他产品并附上联盟链接？当然可以。但如果你能卖掉它，说明你了解它，你大概率应该直接创建你自己的版本。</p><p>联盟营销是指你将你的流量引向别人的产品以获取佣金。</p><p>所以，如果你推广我的 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 课程并且有人购买了，你会获得一定比例的销售分成（顺便说一句，我不提供联盟推广）。</p><p>我在这份清单中提到它的唯一原因，是因为它很适合新手练习。</p><p>通过这个选项，你可以零经验建立起一整个业务：</p><ul><li>围绕联盟产品的主题写内容</li><li>投入精力去建立受众群体</li><li>推广联盟产品</li></ul><p>你不需要技能，也不需要产品。</p><p>因此，在打磨技能和创建产品的过程中，这会是一个很好的练习。</p><p>别被困在这个阶段。去打造你自己的东西。</p><h3 id="_4-数字产品" tabindex="-1">4) 数字产品 <a class="header-anchor" href="#_4-数字产品" aria-label="Permalink to &quot;4) 数字产品&quot;">​</a></h3><p>一旦你拥有足够庞大的受众，并且有能力取得成果，你就可以靠数字产品获得可观的收入。</p><p>我建议尽快打造一个数字产品，这样你就可以快速迭代（因为大多数人的第一个产品都会很糟糕）。</p><p>但是，遵循以下发展路径是合理的：</p><ul><li>通过服务型业务变现</li><li>增长你的受众</li><li>在服务型业务中取得成果</li><li>增长你的受众</li><li>将你在服务型业务中提供的内容转化为数字产品</li><li>增长你的受众</li><li>吸引数字产品买家，并向他们追加销售（upsell）你的服务</li><li>增长你的受众</li><li>随心所欲做你想做的事，停止接客户工作，让你拥有更多自由时间（也给新手腾出市场空间）</li></ul><p>为了简单起见，我们将把数字产品看作<strong>课程、训练营（cohorts）或会员。</strong></p><p>如果你每天能卖出<em>两个</em> 150 美元的数字产品，你的年收入就能达到 6 位数。</p><p>如果算笔账的话，这意味着你需要让 80 个人进入落地页，并实现 2.5% 的转化率。</p><p>如果你写了一篇 X (推特) 的帖子，并在底部推广你的产品，你大约需要 10,000 次左右的曝光量才能达成这个目标。</p><p>如果我只有 1,000 个粉丝，但我有一个有 10,000 粉丝的朋友分享了我的帖子，而且这篇帖子足够有说服力，我几乎可以保证那天我能达成 2 笔销售——而这仅仅依靠很小的粉丝基础。</p><p>很酷的是，即使我没有完成这 2 笔销售，我也在积累受众，他们以后也许会购买我的产品。</p><h3 id="_5-赞助和广告收入" tabindex="-1">5) 赞助和广告收入 <a class="header-anchor" href="#_5-赞助和广告收入" aria-label="Permalink to &quot;5) 赞助和广告收入&quot;">​</a></h3><p>YouTube、newsletter 和播客的赞助能带来不错的收入。</p><p>但你需要拥有大量高互动的受众才能做到这一点。</p><p>对于写作者来说，newsletter 的赞助是最可行的——但为什么要浪费你邮件里的推广空间去给别人的产品做宣传呢？</p><p>这和联盟营销是同一个问题。</p><p>直接打造你自己的产品，去赚取比赞助费多 2 到 10 倍的钱。</p><p>YouTube 的广告收入同理。别再关心那个了。打造你自己的产品或服务，把收入掌控在自己手里。</p><h3 id="_6-实体产品" tabindex="-1">6) 实体产品 <a class="header-anchor" href="#_6-实体产品" aria-label="Permalink to &quot;6) 实体产品&quot;">​</a></h3><p>如果你想获得超高利润，先从数字产品开始，这样你就能把资金投入到实体产品这条收入流水线中。</p><p>对于实体产品，我更倾向于卖那些能与我其他产品互补的东西，或者我自己也在用的东西。</p><p>这就是我推出 FOCI 计划本的原因。</p><p>它和我的业务产品相辅相成，而且也是我自己在用的东西。</p><p>像 SolBrah 或 Greg Doucette 这样的人，销售的就是符合他们训练和营养理念的补剂。</p><p>这是一个很好的一步，尽管它不如数字产品和服务那么简单或暴利。</p><h3 id="_7-软件或服务规模化" tabindex="-1">7) 软件或服务规模化 <a class="header-anchor" href="#_7-软件或服务规模化" aria-label="Permalink to &quot;7) 软件或服务规模化&quot;">​</a></h3><p>在上文中，我提到了你可以打造一款数字产品并停止接客户的工作。</p><p>对很多人来说，这是一个明智之举，因为他们不想应对公司扩张带来的各种要求（比如招聘、系统建设等）。</p><p>仅凭一个人，靠着不断增长的受众和数字产品，你一年的收入就能达到 100 万到 500 万美元（这是顶级水平，需要经过多年的努力和迭代）。</p><p>但是，另一个选择是更进一步。</p><p>你可以规模化（scale）你的服务型业务，或者去开发像软件一类的东西。</p><p>到了这个时候，你已经拥有了如此庞大的受众群体，你想做什么都可以。</p><p>仅凭一个人，靠着不断增长的受众和数字产品，你一年的收入就能达到 100 万到 500 万美元（这是顶级水平，需要经过多年的努力和迭代）。</p><p>但是，另一个选择是更进一步。</p><p>你可以规模化（scale）你的服务型业务，或者去开发像软件一类的东西。</p><p>到了这个时候，你已经拥有了如此庞大的受众群体，你想做什么都可以。</p><h3 id="什么才是赚钱的产品" tabindex="-1">什么才是赚钱的产品？ <a class="header-anchor" href="#什么才是赚钱的产品" aria-label="Permalink to &quot;什么才是赚钱的产品？&quot;">​</a></h3><p>我在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> 里教过这个，但一个“好”产品，本质上是一个用于改变行为的系统。</p><p>你的理念就是你的品牌。</p><p>你的生活方式就是你的产品。</p><p>我的理念是，人们应该打造属于自己的东西，实现个人主权，去做他们想做的事。</p><p>我的产品就是我的写作系统，它能让人们做到这一点。</p><p>我的生活方式是：</p><ul><li>起床</li><li>写作 2 小时（包含激发创造力的休息时间）</li><li>处理我业务中的其他事务</li></ul><p>这相当有吸引力。我拿到了结果，并且拥有一套让我能够做到这一点的独特系统。</p><p>这个系统是在我朝着终极目标（即我打造自己的东西并获得自由的理念）不断试错中诞生的。</p><p>达到这个阶段需要时间。坦然接受这一点吧。</p><p>无论如何，去打造一个产品或服务，并从现在就开始销售，这样你就可以去经历失败了。</p><p>去追求目标，这样你才能真正获得可以变现的经验。</p><p>游手好闲、无所事事只会让你被困在给别人打工卖命的牢笼里。</p><p>朋友们，这封信的内容就到这里了。</p><p>感谢你的阅读。</p><p>Dan</p><hr><p><a href="/en/letters/the-7-digital-career-paths-from-zero-experience-to-advanced">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',202))])}const k=r(s,[["render",c]]);export{g as __pageData,k as default};
